async (page) => {
const errors=[];page.on('pageerror',e=>errors.push(e.message));
const checks=[];const check=(ok,label)=>{if(!ok)throw new Error(label);checks.push(label)};
await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:5173/explorer.html');await page.waitForTimeout(300);
check(await page.locator('.explorer-card').count()===6,'Six créations au chargement');
await page.screenshot({path:'prototype/preview/explorer-desktop.png'});
await page.locator('#query').fill('réservation');await page.locator('#search-form').evaluate(f=>f.requestSubmit());check(await page.locator('.explorer-card').count()===1,'Recherche accentuée');check(page.url().includes('q='),'Recherche dans URL');
await page.reload();check(await page.locator('#query').inputValue()==='réservation','Recherche conservée au rechargement');
await page.locator('[data-reset]').click();await page.locator('[data-filter="kind"]').selectOption('projet');await page.locator('[data-filter="success"]').check();check(await page.locator('.empty-results').count()===1,'Aucune reproduction de projet');await page.screenshot({path:'prototype/preview/explorer-empty.png'});
await page.locator('[data-reset]').first().click();await page.locator('[data-filter="outil"]').selectOption('Claude');check(await page.locator('.explorer-card').count()===2,'Filtre outil');await page.locator('[data-filter="kind"]').selectOption('iteration');check(await page.locator('.explorer-card').count()===1,'Filtres combinés');await page.goBack();check(await page.locator('.explorer-card').count()===2,'Retour arrière restaure les filtres');
await page.locator('[data-reset]').click();await page.locator('#load-more').click();check(await page.locator('.explorer-card').count()===12,'Chargement supplémentaire');await page.locator('#load-more').click();check(await page.locator('.explorer-card').count()===14,'Catalogue complet');
await page.locator('[data-detail="keur-awa"]').first().click();check(await page.locator('#detail').evaluate(d=>d.open),'Aperçu création');await page.locator('#copy-prompt').click();check((await page.locator('#copy-prompt').textContent()).includes('copié'),'Copie du prompt');await page.keyboard.press('Escape');check(!await page.locator('#detail').evaluate(d=>d.open),'Échap ferme aperçu');
await page.locator('[data-tab="sujets"]').click();check(await page.locator('.topic-row').count()===6,'Six discussions');await page.screenshot({path:'prototype/preview/explorer-topics.png'});check(!(await page.locator('#results').textContent()).includes('Invalid Date'),'Dates valides');await page.locator('.topic-row h2 button').first().click();check(await page.locator('.discussion-text').count()===1,'Aperçu discussion');await page.keyboard.press('Escape');
await page.locator('[data-tab="bon-reflexe"]').click();check(await page.locator('.case-row').count()===5,'Cinq cas pratiques');await page.screenshot({path:'prototype/preview/explorer-cases.png'});await page.locator('.case-row h2 button').first().click();await page.locator('[data-answer="1"]').click();check((await page.locator('#quiz-feedback').textContent()).includes('Bonne réponse'),'Cas pratique et correction');await page.locator('#quiz-retry').click();check(await page.locator('[data-answer]:enabled').count()===3,'Réinitialisation du cas');await page.keyboard.press('Escape');
await page.locator('[data-tab="creations"]').click();await page.locator('#tweaks-open').click();for(const [name,value] of Object.entries({accent:'deep',density:'compact',layout:'list',images:'above',effects:'strong',motion:'none'})){await page.locator(`#tweaks-form [name="${name}"]`).selectOption(value);check(await page.locator('html').getAttribute('data-explorer-'+name)===value,'Tweaks '+name);}
await page.screenshot({path:'prototype/preview/explorer-tweaks.png'});await page.locator('#tweaks-form button[type="reset"]').click();check(await page.locator('html').getAttribute('data-explorer-layout')==='grid','Réinitialisation Tweaks');await page.keyboard.press('Escape');
await page.locator('[data-tab="creations"]').focus();await page.keyboard.press('ArrowRight');check(await page.locator('[data-tab="sujets"]').getAttribute('aria-selected')==='true','Navigation clavier onglets');await page.locator('[data-tab="creations"]').click();
for(const width of [1440,768,390,320]){await page.setViewportSize({width,height:900});await page.waitForTimeout(150);check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'Pas de débordement '+width);if(width===390){await page.locator('#mobile-filter-toggle').click();check(await page.locator('#filters').isVisible(),'Ouverture des filtres mobile');await page.locator('#mobile-filter-toggle').click();await page.locator('.menu-toggle').click();check(await page.locator('#mobile-panel').isVisible(),'Menu mobile');await page.keyboard.press('Escape');await page.evaluate(()=>document.activeElement.blur());await page.screenshot({path:'prototype/preview/explorer-mobile.png'});}if(width===768)await page.screenshot({path:'prototype/preview/explorer-tablet.png'});}
await page.setViewportSize({width:1440,height:1000});await page.mouse.move(1400,990);for(let y=0;y<await page.evaluate(()=>document.body.scrollHeight);y+=650){await page.evaluate(y=>window.scrollTo(0,y),y);await page.waitForTimeout(100);}await page.evaluate(()=>window.scrollTo(0,0));await page.screenshot({path:'prototype/preview/explorer-full.png',fullPage:true});
check(await page.locator('img').evaluateAll(imgs=>imgs.filter(i=>i.complete&&!i.naturalWidth).length)===0,'Images chargées');await page.emulateMedia({reducedMotion:'reduce'});check(await page.locator('.explorer-card').first().evaluate(e=>getComputedStyle(e).animationName)==='none','Réduction animations');check(errors.length===0,'Aucune erreur JavaScript');return {checks,errors};
}
